"use client";

import { zodResolver } from "@hookform/resolvers/zod";
import { Mail01Icon } from "@hugeicons/core-free-icons";
import { HugeiconsIcon } from "@hugeicons/react";
import Link from "next/link";
import { useForm } from "react-hook-form";
import { z } from "zod/v3";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { PasswordInput } from "@/components/ui/password-input";
import { EmailInput } from "@/components/ui/email-input";

const loginSchema = z.object({
  email: z.string().email({
    message: "Invalid email address.",
  }),
  password: z.string().min(1, {
    message: "Password is required.",
  }),
  rememberMe: z.boolean(),
});

type LoginFormValues = z.infer<typeof loginSchema>;

export const LoginForm = () => {
  const form = useForm<LoginFormValues>({
    resolver: zodResolver(loginSchema),
    defaultValues: {
      email: "",
      password: "",
      rememberMe: false,
    },
  });

  function onSubmit(values: LoginFormValues) {
    // Handle login submission
    console.log(values);
  }

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)}>
        <div className="space-y-4">
          <FormField
            control={form.control}
            name="email"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Email</FormLabel>
                <FormControl>
                  <EmailInput placeholder="Enter your email" {...field} />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="password"
            render={({ field }) => (
              <FormItem>
                <div className="flex items-center justify-between">
                  <FormLabel>Password</FormLabel>
                  <Link
                    href="/auth/forgot-password"
                    className="text-muted-foreground text-xs hover:text-foreground transition-colors"
                  >
                    Forgot password?
                  </Link>
                </div>
                <FormControl>
                  <PasswordInput placeholder="Enter your password" {...field} />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="rememberMe"
            render={({ field }) => (
              <FormItem className="flex flex-row items-center space-x-2 space-y-0">
                <FormControl>
                  <Checkbox
                    checked={field.value}
                    onCheckedChange={field.onChange}
                  />
                </FormControl>
                <FormLabel className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70">
                  Remember me
                </FormLabel>
              </FormItem>
            )}
          />
        </div>

        <Button className="mt-6 w-full" size="lg">
          <HugeiconsIcon
            icon={Mail01Icon}
            className="mr-2"
            size={20}
            strokeWidth={1.5}
          />
          Login with Email
        </Button>
      </form>
    </Form>
  );
};

"use client";

import { zodResolver } from "@hookform/resolvers/zod";
import { Mail01Icon } from "@hugeicons/core-free-icons";
import { HugeiconsIcon } from "@hugeicons/react";
import { useForm } from "react-hook-form";
import { z } from "zod/v3";
import { Button } from "@/components/ui/button";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { PasswordInput } from "@/components/ui/password-input";
import { EmailInput } from "@/components/ui/email-input";

const formSchema = z.object({
  email: z.string().email({
    message: "Invalid email address.",
  }),
  password: z.string().min(8, {
    message: "Password must be at least 8 characters.",
  }),
});

export const SignUpForm = () => {
  const form = useForm<z.infer<typeof formSchema>>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      email: "",
      password: "",
    },
  });

  function onSubmit(values: z.infer<typeof formSchema>) {
    // Handle form submission
    console.log(values);
  }

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)}>
        <div className="space-y-6">
          <FormField
            control={form.control}
            name="email"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Email</FormLabel>
                <FormControl>
                  <EmailInput placeholder="Enter your email" {...field} />
                </FormControl>
                <FormDescription>
                  We'll never share your email with anyone else.
                </FormDescription>
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="password"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Password</FormLabel>
                <FormControl>
                  <PasswordInput placeholder="Enter your password" {...field} />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />
        </div>
        <Button className="mt-6 w-full" size="lg">
          <HugeiconsIcon
            icon={Mail01Icon}
            className="mr-2"
            size={20}
            strokeWidth={1.5}
          />
          Continue with Email
        </Button>
      </form>
    </Form>
  );
};

"use client";

import React from "react";
import { SvglIcon } from "@/components/ui/svgl-icon";

interface GoogleLogoProps extends React.ComponentPropsWithoutRef<"span"> {
  /** Taille de l'icône en pixels */
  size?: number;
}

/**
 * Composant GoogleLogo réutilisant SvglIcon pour éviter la redondance.
 * Extrait du fichier d'icônes d'authentification pour utiliser l'API SVGL.
 */
export const GoogleLogo = ({ className, size, ...props }: GoogleLogoProps) => {
  return (
    <SvglIcon 
      filename="google.svg" 
      size={size} 
      className={className} 
      {...props} 
    />
  );
};

export default GoogleLogo;

"use client";

import * as React from "react";
import { HugeiconsIcon } from "@hugeicons/react";
import { Mail01Icon } from "@hugeicons/core-free-icons";

import { cn } from "@/lib/utils";

export interface EmailInputProps extends React.ComponentProps<"input"> {}

const EmailInput = React.forwardRef<HTMLInputElement, EmailInputProps>(
  ({ className, ...props }, ref) => {
    return (
      <div
        className={cn(
          "flex h-8 items-center overflow-hidden rounded-lg border border-input bg-transparent transition-colors focus-within:border-ring dark:bg-input/30",
          className,
        )}
      >
        <div className="flex items-center justify-center pl-2.5 text-muted-foreground">
          <HugeiconsIcon icon={Mail01Icon} size={16} strokeWidth={1.5} />
        </div>

        <input
          {...props}
          ref={ref}
          type="email"
          className="h-full min-w-0 flex-1 bg-transparent px-2.5 text-sm text-foreground placeholder:text-muted-foreground outline-none"
        />
      </div>
    );
  },
);
EmailInput.displayName = "EmailInput";

export { EmailInput };

"use client";

import * as React from "react";
import { HugeiconsIcon } from "@hugeicons/react";
import { ViewIcon, ViewOffIcon, LockKeyIcon } from "@hugeicons/core-free-icons";

import { cn } from "@/lib/utils";

export interface PasswordInputProps extends React.ComponentProps<"input"> {}

const PasswordInput = React.forwardRef<HTMLInputElement, PasswordInputProps>(
  ({ className, ...props }, ref) => {
    const [showPassword, setShowPassword] = React.useState(false);

    return (
      <div
        className={cn(
          "flex h-8 items-center overflow-hidden rounded-lg border border-input bg-transparent transition-colors focus-within:border-ring dark:bg-input/30",
          className,
        )}
      >
        <div className="flex items-center justify-center pl-2.5 text-muted-foreground">
          <HugeiconsIcon icon={LockKeyIcon} size={16} strokeWidth={1.5} />
        </div>

        <input
          {...props}
          ref={ref}
          type={showPassword ? "text" : "password"}
          className="h-full min-w-0 flex-1 bg-transparent px-2.5 text-sm text-foreground placeholder:text-muted-foreground outline-none"
        />

        <div className="h-4 w-px shrink-0 bg-border" />

        <button
          type="button"
          onClick={() => setShowPassword((prev) => !prev)}
          tabIndex={-1}
          className="flex h-full items-center justify-center px-2.5 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
        >
          <HugeiconsIcon
            icon={showPassword ? ViewOffIcon : ViewIcon}
            size={16}
            strokeWidth={1.5}
          />
          <span className="sr-only">
            {showPassword
              ? "Masquer le mot de passe"
              : "Afficher le mot de passe"}
          </span>
        </button>
      </div>
    );
  },
);
PasswordInput.displayName = "PasswordInput";

export { PasswordInput };

import Login from "@/components/authentication/login";

export default function LoginPage() {
  return <Login />;
}

import SignUp from "@/components/authentication/signup";

export default function SignUpPage() {
  return <SignUp />;
}
